<script setup lang="ts">
import { computed, ref, watch } from "vue";
import type { TimeSeriesDescriptor } from "../operations/time-series-port";
import { defaultIndicators, indicatorError, type IndicatorSettings } from "../operations/series-indicators";
const props = defineProps<{ catalog: readonly TimeSeriesDescriptor[]; settings: readonly IndicatorSettings[]; preferred?: string }>();
const emit = defineEmits<{ apply: [settings: IndicatorSettings]; clear: []; close: [] }>();
const sourceId = ref(props.preferred ?? props.settings[0]?.sourceId ?? props.catalog[0]?.id ?? "");
const draft = ref<IndicatorSettings>(defaultIndicators(sourceId.value));
const error = computed(() => indicatorError(draft.value) || (props.settings.length >= 12 && !props.settings.some(item => item.sourceId === sourceId.value) ? "Up to 12 sources can have indicators. Clear an existing source first." : ""));
watch([sourceId, () => props.settings], () => { draft.value = { ...(props.settings.find(item => item.sourceId === sourceId.value) ?? defaultIndicators(sourceId.value)) }; }, { immediate: true });
</script>

<template>
  <section class="indicator-controls" aria-label="Indicator settings">
    <header><div><span class="eyebrow">TIME SERIES</span><h2>Indicators</h2></div><button aria-label="Close indicator settings" @click="emit('close')">×</button></header>
    <div class="study-source"><label>Source<select v-model="sourceId" aria-label="Indicator source"><option v-for="source in catalog" :key="source.id" :value="source.id">{{ source.label }}</option></select></label><p>Periods count observed samples. Calculated before chart zoom, using up to 24 hours of retained history.</p></div>
    <div class="study-options">
      <div class="study-option"><label class="study-toggle"><input v-model="draft.ewma" type="checkbox" />EWMA overlay</label><p>Smooth the original readings.</p><label class="period">Span<input v-model.number="draft.span" aria-label="EWMA span" type="number" min="2" max="500" step="1" /></label></div>
      <div class="study-option"><label class="study-toggle"><input v-model="draft.zscore" type="checkbox" />Rolling z-score</label><p>0 = mean · ±1 = one standard deviation.</p><label class="period">Window<input v-model.number="draft.window" aria-label="Statistics window" type="number" min="2" max="500" step="1" /></label></div>
      <div class="study-option"><label class="study-toggle"><input v-model="draft.deviation" type="checkbox" />Standard deviation</label><p>Trailing volatility in the original units.</p><span class="shared-window">Uses the {{ draft.window }}-sample statistics window</span></div>
      <div class="study-option"><label class="study-toggle"><input v-model="draft.macd" type="checkbox" />MACD</label><p>Trend, signal line, and momentum histogram.</p><div class="macd-periods"><label class="period">Fast<input v-model.number="draft.fast" aria-label="MACD fast period" type="number" min="2" max="500" step="1" /></label><label class="period">Slow<input v-model.number="draft.slow" aria-label="MACD slow period" type="number" min="2" max="500" step="1" /></label><label class="period">Signal<input v-model.number="draft.signal" aria-label="MACD signal period" type="number" min="2" max="500" step="1" /></label></div></div>
    </div>
    <footer><span v-if="error" role="alert">{{ error }}</span><span v-else>Local calculation · No model calls · Saved in this browser</span><div><button v-if="settings.length" @click="emit('clear')">Clear all</button><button class="apply-studies" :disabled="Boolean(error) || !sourceId" @click="emit('apply', {...draft})">Apply indicators</button></div></footer>
  </section>
</template>

